function solve(input) {
  const { document, pointer } = input;

  if (typeof pointer !== 'string') return { found: false };
  if (pointer === '') return { found: true, value: document };
  if (pointer[0] !== '/') return { found: false };

  const tokens = pointer.slice(1).split('/');
  let current = document;

  for (const token of tokens) {
    const decoded = token.replace(/~1/g, '/').replace(/~0/g, '~');

    if (current === null || current === undefined) return { found: false };

    if (Array.isArray(current)) {
      if (!/^(0|[1-9][0-9]*)$/.test(decoded)) return { found: false };
      const idx = Number(decoded);
      if (idx >= current.length) return { found: false };
      current = current[idx];
    } else if (typeof current === 'object') {
      if (!Object.prototype.hasOwnProperty.call(current, decoded)) return { found: false };
      current = current[decoded];
    } else {
      return { found: false };
    }
  }

  return { found: true, value: current };
}

